    const directory = mkdtempSync(path.join(os.tmpdir(), 'uv-media-test-'));
    const wav = path.join(directory, 'silence.wav');
    writeFileSync(wav, silentWav());
    const uri = `file:///${wav.replace(/\\/g, '/').replace(/'/g, "''")}`;

